<template><div class="space-y-4 p-4"><h1 class="text-xl font-bold text-slate-800">Wallet and payouts</h1><div v-if="wallet" class="m-card"><p class="text-xs text-slate-400">Available</p><p class="text-2xl font-bold text-emerald-600">{{ money(wallet.available_balance_minor,wallet.currency) }}</p><p class="text-xs text-slate-400">Locked {{ money(wallet.locked_balance_minor,wallet.currency) }}</p></div><div v-for="item in payouts" :key="item.id" class="m-card"><p class="font-semibold">{{ money(item.amount_minor,item.currency) }}</p><p class="text-xs text-slate-400">{{ item.status }}</p></div></div></template>
<script setup lang="ts">definePageMeta({middleware:['auth']});const {apiFetch}=useApi();const wallet=ref<any>();const payouts=ref<any[]>([]);const money=(v:number,c:string)=>new Intl.NumberFormat(undefined,{style:'currency',currency:c}).format(v/100);onMounted(async()=>{const [w,p]=await Promise.all([apiFetch<any>('/cebu-trade/wallet'),apiFetch<any>('/cebu-trade/payouts')]);wallet.value=w;payouts.value=p.items})</script>
